@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  repository: AncRepository,
  syncViewModel: SyncViewModel,
  onPatientClick: (String) -> Unit,
) {
  val scope = rememberCoroutineScope()
  var patients by remember { mutableStateOf<List<PatientItem>>(emptyList()) }
  var isLoading by remember { mutableStateOf(true) }
  val isSyncing by syncViewModel.isSyncing.collectAsState()
  val syncStatus by syncViewModel.syncState.collectAsState()

  fun refreshPatients() {
    scope.launch {
      isLoading = true
      patients = repository.getPregnantPatients()
      isLoading = false
    }
  }

  // Refresh patients when screen opens or when sync completes
  LaunchedEffect(Unit) {
    refreshPatients()
  }

  LaunchedEffect(isSyncing) {
    if (!isSyncing) {
      refreshPatients()
    }
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              "ANC Register",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold,
            )
            if (syncStatus != null) {
              Text(
                syncStatus.orEmpty(),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
              )
            }
          }
        },
        actions = {
          IconButton(
            onClick = {
              syncViewModel.syncNow { refreshPatients() }
            },
            enabled = !isSyncing,
          ) {
            if (isSyncing) {
              CircularProgressIndicator(
                modifier = Modifier.size(24.dp),
                strokeWidth = 2.dp,
              )
            } else {
              Icon(
                imageVector = Icons.Default.Refresh,
                contentDescription = "Sync from server",
              )
            }
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding),
    ) {
      if (isLoading && patients.isEmpty()) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      } else if (patients.isEmpty()) {
        Column(
          modifier = Modifier
            .fillMaxSize()
            .padding(24.dp),
          horizontalAlignment = Alignment.CenterHorizontally,
          verticalArrangement = Arrangement.Center,
        ) {
          Text(
            "No patients currently registered.",
            style = MaterialTheme.typography.bodyLarge,
          )
          Spacer(modifier = Modifier.height(16.dp))
          Button(
            onClick = {
              syncViewModel.syncNow { refreshPatients() }
            },
            enabled = !isSyncing,
          ) {
            Text("Sync from Server")
          }
        }
      } else {
        LazyColumn(
          modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          items(patients, key = { it.id }) { patient ->
            PatientCard(patient = patient, onClick = { onPatientClick(patient.id) })
          }
        }
      }
    }
  }
}

@Composable
fun PatientCard(
  patient: PatientItem,
  onClick: () -> Unit,
) {
  val dateFormatter = remember { DateTimeFormatter.ofPattern("MMM d, yyyy") }

  Card(
    modifier = Modifier
      .fillMaxWidth()
      .clickable(onClick = onClick),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.surface,
    ),
  ) {
    Column(
      modifier = Modifier
        .fillMaxWidth()
        .padding(16.dp),
    ) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            imageVector = Icons.Default.Person,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.primary,
            modifier = Modifier.size(24.dp),
          )
          Spacer(modifier = Modifier.width(8.dp))
          Text(
            text = patient.name,
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold,
          )
        }
        if (patient.age != null) {
          Text(
            text = "Age: ${patient.age}",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
          )
        }
      }

      Spacer(modifier = Modifier.height(12.dp))

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        val eddText = patient.edd?.let {
          "EDD: ${it.format(dateFormatter)}"
        } ?: "EDD: Not set"

        SuggestionChip(
          onClick = {},
          label = { Text(eddText) },
          icon = {
            Icon(
              imageVector = Icons.Default.CalendarToday,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
            )
          },
          colors = SuggestionChipDefaults.suggestionChipColors(
            containerColor = MaterialTheme.colorScheme.secondaryContainer,
            labelColor = MaterialTheme.colorScheme.onSecondaryContainer,
          ),
        )

        val gaText = patient.gestationalAgeWeeks?.let {
          "$it weeks"
        } ?: "GA: Unknown"

        SuggestionChip(
          onClick = {},
          label = { Text(gaText) },
          icon = {
            Icon(
              imageVector = Icons.Default.Schedule,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
            )
          },
          colors = SuggestionChipDefaults.suggestionChipColors(
            containerColor = MaterialTheme.colorScheme.tertiaryContainer,
            labelColor = MaterialTheme.colorScheme.onTertiaryContainer,
          ),
        )
      }
    }
  }
}

