@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PatientDetailScreen(
  patientId: String,
  repository: AncRepository,
  onBackClick: () -> Unit,
  onRecordVisitClick: (String) -> Unit,
) {
  val scope = rememberCoroutineScope()
  var detail by remember { mutableStateOf<PatientDetail?>(null) }
  var isLoading by remember { mutableStateOf(true) }

  fun loadDetail() {
    scope.launch {
      isLoading = true
      detail = runCatching { repository.getPatientDetail(patientId) }.getOrNull()
      isLoading = false
    }
  }

  LaunchedEffect(patientId) {
    loadDetail()
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Text(
            detail?.patient?.name ?: "Patient Details",
            fontWeight = FontWeight.Bold,
          )
        },
        navigationIcon = {
          IconButton(onClick = onBackClick) {
            Icon(
              imageVector = Icons.AutoMirrored.Filled.ArrowBack,
              contentDescription = "Back",
            )
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(
        onClick = { onRecordVisitClick(patientId) },
        icon = { Icon(Icons.Default.Add, contentDescription = null) },
        text = { Text("Record New Visit") },
      )
    },
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding),
    ) {
      if (isLoading && detail == null) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      } else if (detail == null) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          Text("Failed to load patient details.")
        }
      } else {
        val currentDetail = detail!!
        LazyColumn(
          modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
          verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
          // Patient Summary Card
          item {
            Card(
              modifier = Modifier.fillMaxWidth(),
              colors = CardDefaults.cardColors(
                containerColor = MaterialTheme.colorScheme.surfaceVariant,
              ),
            ) {
              Column(
                modifier = Modifier
                  .fillMaxWidth()
                  .padding(16.dp),
              ) {
                Row(
                  verticalAlignment = Alignment.CenterVertically,
                ) {
                  Icon(
                    imageVector = Icons.Default.Person,
                    contentDescription = null,
                    modifier = Modifier.size(28.dp),
                    tint = MaterialTheme.colorScheme.primary,
                  )
                  Spacer(modifier = Modifier.width(8.dp))
                  Column {
                    Text(
                      text = currentDetail.patient.name,
                      style = MaterialTheme.typography.titleLarge,
                      fontWeight = FontWeight.Bold,
                    )
                    val dobText = currentDetail.patient.birthDate?.let { "DOB: $it" } ?: ""
                    val ageText = currentDetail.patient.age?.let { " ($it yrs)" } ?: ""
                    if (dobText.isNotEmpty()) {
                      Text(
                        text = "$dobText$ageText",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                      )
                    }
                  }
                }

                Spacer(modifier = Modifier.height(12.dp))

                Row(
                  modifier = Modifier.fillMaxWidth(),
                  horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                  val eddStr = currentDetail.patient.edd?.toString() ?: "Not set"
                  SuggestionChip(
                    onClick = {},
                    label = { Text("EDD: $eddStr") },
                    icon = {
                      Icon(
                        imageVector = Icons.Default.CalendarToday,
                        contentDescription = null,
                        modifier = Modifier.size(16.dp),
                      )
                    },
                  )

                  val gaStr = currentDetail.patient.gestationalAgeWeeks?.let { "$it weeks" } ?: "Unknown"
                  SuggestionChip(
                    onClick = {},
                    label = { Text("GA: $gaStr") },
                  )
                }
              }
            }
          }

          // Visits Header
          item {
            Text(
              text = "Past ANC Visits",
              style = MaterialTheme.typography.titleMedium,
              fontWeight = FontWeight.Bold,
              modifier = Modifier.padding(top = 8.dp),
            )
          }

          if (currentDetail.visits.isEmpty()) {
            item {
              Box(
                modifier = Modifier
                  .fillMaxWidth()
                  .padding(32.dp),
                contentAlignment = Alignment.Center,
              ) {
                Text(
                  "No past ANC visits recorded yet.",
                  style = MaterialTheme.typography.bodyMedium,
                  color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
              }
            }
          } else {
            items(currentDetail.visits, key = { it.encounterId }) { visit ->
              VisitCard(visit = visit)
            }
          }

          // Spacer for FAB clearance
          item {
            Spacer(modifier = Modifier.height(64.dp))
          }
        }
      }
    }
  }
}

@Composable
fun VisitCard(visit: VisitItem) {
  Card(
    modifier = Modifier.fillMaxWidth(),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.surface,
    ),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
  ) {
    Column(
      modifier = Modifier
        .fillMaxWidth()
        .padding(16.dp),
    ) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            imageVector = Icons.Default.CalendarToday,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.primary,
            modifier = Modifier.size(20.dp),
          )
          Spacer(modifier = Modifier.width(8.dp))
          Text(
            text = "Visit Date: ${visit.date}",
            style = MaterialTheme.typography.titleSmall,
            fontWeight = FontWeight.Bold,
          )
        }
        if (visit.gestationalAgeWeeks != null) {
          Text(
            text = "${visit.gestationalAgeWeeks} wks GA",
            style = MaterialTheme.typography.labelMedium,
            color = MaterialTheme.colorScheme.secondary,
          )
        }
      }

      Spacer(modifier = Modifier.height(12.dp))

      // Vitals Row: Weight, Blood Pressure, Hemoglobin (if recorded)
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(16.dp),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        if (visit.weightKg != null) {
          Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
              imageVector = Icons.Default.FitnessCenter,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
              tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(
              text = visit.weightKg,
              style = MaterialTheme.typography.bodyMedium,
            )
          }
        }

        if (visit.bloodPressure != null) {
          Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
              imageVector = Icons.Default.Favorite,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
              tint = MaterialTheme.colorScheme.error,
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(
              text = "${visit.bloodPressure} mmHg",
              style = MaterialTheme.typography.bodyMedium,
            )
          }
        }

        // Hemoglobin if recorded
        if (visit.hemoglobin != null) {
          Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
              imageVector = Icons.Default.MedicalServices,
              contentDescription = null,
              modifier = Modifier.size(16.dp),
              tint = MaterialTheme.colorScheme.primary,
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(
              text = "Hb: ${visit.hemoglobin}",
              style = MaterialTheme.typography.bodyMedium,
              fontWeight = FontWeight.SemiBold,
            )
          }
        }
      }

      // Danger signs (if recorded)
      if (visit.dangerSigns.isNotEmpty()) {
        Spacer(modifier = Modifier.height(8.dp))
        Row(
          verticalAlignment = Alignment.CenterVertically,
        ) {
          Icon(
            imageVector = Icons.Default.Warning,
            contentDescription = null,
            modifier = Modifier.size(16.dp),
            tint = MaterialTheme.colorScheme.error,
          )
          Spacer(modifier = Modifier.width(4.dp))
          Text(
            text = "Danger signs: ${visit.dangerSigns.joinToString(", ")}",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.error,
          )
        }
      }

      // Notes (if recorded)
      if (!visit.notes.isNullOrBlank()) {
        Spacer(modifier = Modifier.height(8.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodySmall,
          color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
      }
    }
  }
}

