import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.ancapp.data.AncRepository
import com.example.ancapp.sync.SyncViewModel
import com.example.ancapp.ui.NewVisitScreen
import com.example.ancapp.ui.PatientDetailScreen
import com.example.ancapp.ui.RegisterScreen
import dev.ohs.fhir.engine.FhirEngineProvider

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
          val navController = rememberNavController()
          val engine = remember { FhirEngineProvider.getInstance(applicationContext) }
          val repository = remember { AncRepository(engine) }
          val syncViewModel: SyncViewModel = viewModel()

          // Trigger sync on app launch
          LaunchedEffect(Unit) {
            syncViewModel.syncNow()
          }

          NavHost(
            navController = navController,
            startDestination = "register",
          ) {
            composable("register") {
              RegisterScreen(
                repository = repository,
                syncViewModel = syncViewModel,
                onPatientClick = { patientId ->
                  navController.navigate("patientDetail/$patientId")
                },
              )
            }

            composable(
              route = "patientDetail/{patientId}",
              arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
            ) { backStackEntry ->
              val patientId = backStackEntry.arguments?.getString("patientId") ?: return@composable
              PatientDetailScreen(
                patientId = patientId,
                repository = repository,
                onBackClick = { navController.popBackStack() },
                onRecordVisitClick = { id ->
                  navController.navigate("newVisit/$id")
                },
              )
            }

            composable(
              route = "newVisit/{patientId}",
              arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
            ) { backStackEntry ->
              val patientId = backStackEntry.arguments?.getString("patientId") ?: return@composable
              NewVisitScreen(
                patientId = patientId,
                repository = repository,
                syncViewModel = syncViewModel,
                onNavigateBack = { navController.popBackStack() },
              )
            }
          }
        }
      }
    }
  }
}

